import numpy as np, time
P720=np.arange(720)
sites=[f"resid{L}@{p}" for L in range(13) for p in range(5)]
A=acts(P720,sites); M={s:A[s].mean(0) for s in sites}
base=run(P720).argmax(1)
t0=time.time()
R=np.zeros((13,5))
for L in range(13):
    for p in range(5):
        s=f"resid{L}@{p}"
        R[L,p]=(run(P720,{s:M[s]}).argmax(1)!=base).mean()
print("t",time.time()-t0)
for L in range(13): print(L," ".join(f"{R[L,p]:.2f}" for p in range(5)))
